SELECT EXISTS ( SELECT 1 FROM email_attachments a JOIN email_messages m ON a.message_id = m.id LEFT JOIN document_email de ON de.email_attachment_id = a.id WHERE m.link_id = $2 AND m.provider_id = $1 AND a.reference_url IS NULL AND de.email_attachment_id IS NULL AND a.upload_claimed_at IS NULL AND a.filename IS NOT NULL AND ( a.mime_type = ANY($3::text[]) OR ( a.mime_type = 'application/octet-stream' AND UPPER(SUBSTRING(a.filename FROM '\.([^.]+)$')) = ANY($4::text[]) ) ) ) AS "has_candidate!"
